// Generated by scripts/build-exemplars.mjs — edit src/gallery/, not this file.

import { useMemo } from 'react';
import * as d3 from 'd3';

type AgeBand = { name: string; value: number };

/** One slice per row: a label and the quantity it represents. */
export type Data = { name: string; value: number }[];

/** Estimated U.S. population by age band, 2015 (U.S. Census). */
const population: AgeBand[] = [
  { name: '<5', value: 19912018 },
  { name: '5-9', value: 20501982 },
  { name: '10-14', value: 20679786 },
  { name: '15-19', value: 21354481 },
  { name: '20-24', value: 22604232 },
  { name: '25-29', value: 21698010 },
  { name: '30-34', value: 21183639 },
  { name: '35-39', value: 19855782 },
  { name: '40-44', value: 20796128 },
  { name: '45-49', value: 21370368 },
  { name: '50-54', value: 22525490 },
  { name: '55-59', value: 21001947 },
  { name: '60-64', value: 18415681 },
  { name: '65-69', value: 14547446 },
  { name: '70-74', value: 10587721 },
  { name: '75-79', value: 7730129 },
  { name: '80-84', value: 5811429 },
  { name: '≥85', value: 5938752 }
];

const MARGIN = { top: 10, right: 10, bottom: 10, left: 10 };
const MAX_HEIGHT = 500;
const LABEL_RADIUS_RATIO = 0.8;
/** Radians below which a wedge is too thin to hold a second line of text. */
const VALUE_LABEL_MIN_ANGLE = 0.25;

const formatCount = d3.format(',');

export default function PieChart({ data = population, width }: { data?: Data; width: number }) {
  const height = Math.min(Math.round(width * 0.54), MAX_HEIGHT);
  const radius =
    Math.min(width - MARGIN.left - MARGIN.right, height - MARGIN.top - MARGIN.bottom) / 2;

  const color = useMemo(
    () =>
      d3
        .scaleOrdinal<string, string>()
        .domain(data.map((d) => d.name))
        .range(
          d3
            .quantize((t) => d3.interpolateSpectral(t * 0.8 + 0.1), data.length)
            .reverse()
        ),
    [data]
  );

  const arcs = useMemo(
    () =>
      d3
        .pie<AgeBand>()
        .sort(null)
        .value((d) => d.value)(data),
    [data]
  );

  const arc = useMemo(
    () => d3.arc<d3.PieArcDatum<AgeBand>>().innerRadius(0).outerRadius(radius),
    [radius]
  );

  const labelArc = useMemo(() => {
    const labelRadius = radius * LABEL_RADIUS_RATIO;
    return d3.arc<d3.PieArcDatum<AgeBand>>().innerRadius(labelRadius).outerRadius(labelRadius);
  }, [radius]);

  if (width === 0) return null;

  return (
    <svg
      viewBox={`${-width / 2} ${-height / 2} ${width} ${height}`}
      width="100%"
      height={height}
      role="img"
      aria-label="Pie chart of estimated United States population by age band in 2015"
    >
      <g stroke="var(--panel)">
        {arcs.map((d) => (
          <path key={d.data.name} d={arc(d) ?? undefined} fill={color(d.data.name)}>
            <title>{`${d.data.name}: ${formatCount(d.data.value)}`}</title>
          </path>
        ))}
      </g>
      <g textAnchor="middle" fontSize={11} fill="var(--bg)">
        {arcs.map((d) => {
          const [cx, cy] = labelArc.centroid(d);
          return (
            <text key={d.data.name} transform={`translate(${cx},${cy})`}>
              <tspan y="-0.4em" fontWeight="bold">
                {d.data.name}
              </tspan>
              {d.endAngle - d.startAngle > VALUE_LABEL_MIN_ANGLE && (
                <tspan x={0} y="0.7em" fillOpacity={0.7}>
                  {formatCount(d.data.value)}
                </tspan>
              )}
            </text>
          );
        })}
      </g>
    </svg>
  );
}
